quests[38439] = { id = 38439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38440] = { id = 38440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", progress = "How goes the assault, sir?", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Iron Horde forces at the Fel Forge in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38441] = { id = 38441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on The Fel Forge", description = "The Iron Horde is growing stronger each day as their war machines are empowered with fel magic. We have even obtained word that they are constructing a Fel Reaver!\n\nHead to the Fel Forge and destroy their forces before we are overwhelmed.", completion = "Word of your success has already been passed on by our scouts. \n\nLok'tar!", objectives = "Assault the Iron Horde forces at the Fel Forge in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38442] = { id = 38442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenger" }
quests[38443] = { id = 38443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Repose", description = "For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed.\n\nYour saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos.\n\nThe Azurewing Repose is to the northeast. I will meet you there, {name}.", completion = "He is... he's dying! Senegos is possibly the oldest dragon alive. We cannot simply let him slip away.\n\nThere is something not quite right with the magic energy here, I can feel it.", objectives = "Speak with Archmage Khadgar at the Azurewing Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38444] = { id = 38444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In, Through, and Beyond!", description = "Gul'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we've seen before - they're empowered with fel energy.\n\nOur enemies think this pass is impregnable. Let's prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!", completion = "Don't worry, I have a taskforce coming in a bit to clean the rest up. We should move before their runners get back to Gul'dan.", objectives = "Destroy the Fel Defense Cannon covering the gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38445] = { id = 38445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault Base", description = "While you were playing with fel fire, I've located the perfect position for an assault outpost.\n\nFollow me and we can get this base started!", completion = "The easy part is done, now comes the hard part.", objectives = "Establish your assault base in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38446] = { id = 38446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander in the Field!", description = "This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though.\n\nPerhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.", progress = "There's a lot to see here isn't there?", completion = "This will be a difficult campaign to be sure.", objectives = "Get reports from various scouts in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38449] = { id = 38449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Temple of Sha'naar", description = "Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", completion = "Welcome back, General. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38451] = { id = 38451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Geir Gutslice" }
quests[38452] = { id = 38452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hidden Demon" }
quests[38453] = { id = 38453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "Collect tracking maps to find the location of the killer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38454] = { id = 38454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfortunate Circumstances", description = "The Illidari ask us to trust them, but all I see is failure. Look around... this entire city has been lost!\n\nI tracked down the pit lord Malinoth here and brought what few of my men I had with me to put an end to this depravity. They were not enough.\n\nThe brute threw us in this cage and was 'saving us for later.' We need your help, {name}.", objectives = "Free Lady Liadrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38455] = { id = 38455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzied Furbolgs", description = "I would help you seek audience with the Archdruid, but we have a difficult situation on our hands.\n\nThe nearby furbolgs have gone into a frenzied rage.\n\nFor days, it has been all we can do to protect our grove from their aggression.\n\nThey have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream.\n\nIn order to awaken them, we must first get past the furbolg.", completion = "The conflict against the furbolgs is abated, for now.", objectives = "Kill 8 Smolderhide furbolgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38457] = { id = 38457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Putre'thar" }
quests[38458] = { id = 38458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", completion = "I was too late to give you the message. I am truly sorry. These poor shaman... if only I had known sooner!\n\nGul'dan has prepared everything for his ritual. He will use the cipher and his own fel magic to corrupt an elemental lord and use it to sunder the elemental link to the land. This will cause a massive upheaval across Draenor!", objectives = "Speak with the warlock at Vol'mar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38459] = { id = 38459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Trials", description = "<As the raven stares into your eyes, an odd voice fills your mind.>\n\nI know who you are, champion, and I know what you seek.\n\nCome to me, if you think yourself truly worthy.", completion = "I'm sure your head is filled with questions. Answers will come, in time.\n\nI am Havi, and my words are those of the Valarjar - the glorious keepers of the Halls of Valor. \n\nYou will need my help if it is the Aegis you seek. Oh yes, I know your goals outsider. As I know many things...", objectives = "Find Havi near Aggramar's Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38460] = { id = 38460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Make A Deal", description = "Hey there!\n\nYou seem like a gullib- er... um... \"intelligent\" type.\n\nI propose a deal.\n\nI need a minion to be my muscle to help me acquire a few special... \"ingredients\" for a ritual.\n\nIn exchange, I'll give you my former master to do with whatever you demon-slaying types do with demons.\n\nIf you are interested, just sign here. In blood, please.", progress = "Yeah! Yeah! You read the contract? I made it myself. Really good binding clauses in there.", completion = "At last! A minion of my very own!", objectives = "Sign Daglop's contract.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38461] = { id = 38461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Guarms Mate (Fenri)" }
quests[38462] = { id = 38462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Barrier", description = "The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance.\n\nIf you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.", completion = "Not a moment too soon. He has summoned something, I fear the ritual is close to complete.", objectives = "Collect the Black Candle, the Tome of Protection, and the Shadowblade at the Fel Forge and bring them to Oronok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38463] = { id = 38463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", completion = "You have saved us all. The Cipher has become fragmented with Cyrukh's death. This means its guardians can hide the shards all over Draenor so the chances of piecing it together will be impossible.\n\nThis victory will echo through the halls of your warriors and spur them to greater deeds. Gul'dan can continue plotting... he will fail...", objectives = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38465] = { id = 38465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shyama the Dreaded" }
