quests[38471] = { id = 38471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Kiss" }
quests[38472] = { id = 38472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitewater Typhoon" }
quests[38473] = { id = 38473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Thorignir", description = "In the summit of storms the dragons await. Born of the gods, they will test your will. \n\nThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.\n\nA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", completion = "It's good to see you, {name}. Greymane sent me away to scout this village for more information on the Aegis. \n\nI haven't gleaned much so far, other than that the locals here don't seem so friendly. Of course, when are they ever?\n\nI hope your search fares better.", objectives = "Meet with Lorna Crowley outside of Hrydshal to begin the trial of the Thorignir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38474] = { id = 38474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 001 - Hrydshal - ZTO" }
