quests[38496] = { id = 38496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: BH Master Scout" }
quests[38498] = { id = 38498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 018 - Maw of Nashal - ZTO" }
quests[38499] = { id = 38499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange New Ores", description = "You smell that, smith? Ahhhh... that there's the smell of opportunity.\n\nDalaran's taken us to some strange new shores, filled with mysterious metals. I'm tethered to my shop here, but you... you've got the freedom to explore and mine at will.\n\nBring me something interesting, and we'll see what we can make with it.", progress = "Come up with anything interesting?", completion = "Fascinating...", objectives = "Obtain 10 Leystone Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38500] = { id = 38500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leysmithing Mastery", description = "Well, now that we have the flux we can put it to work and see how it goes. Why don't you take a crack at it this time and make some gauntlets for me. I'll observe your work... from a distance.", progress = "Did it work? I haven't heard an explosion yet.", completion = "Excellent work! This new flux may do wonders for other craftable materials as well.", objectives = "Follow Alard Schmied's recipes in your Blacksmithing recipe list to build some Handcrafted Leystone Gauntlets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38501] = { id = 38501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecoil Hammerwork", description = "There may be a way to jump-start our research into leystone.\n\nI've heard reports of naga camps down in Azsuna. If they've been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves.\n\nBe on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.", progress = "I still marvel at how quickly those things can swim in plate armor.", completion = "Of course! They've found their way around the welding problem by simply crafting their armor out of one solid piece of metal.\n\nThe shoulderpads I should have figured out on my own, but their work on the breastplate really is remarkable.\n\nHere, let me jot down a few patterns so you can make these yourself.", objectives = "Obtain a Masterwork Hatecoil Breastplate and a pair of Masterwork Hatecoil Pauldrons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38502] = { id = 38502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Methods of the Nightfallen", description = "I have a theory, {name}.\n\nHave you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary.\n\nThese fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps.\n\nBring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!", progress = "Hopefully we can extract something useful.", completion = "If my guess is correct, the answer to our welding problem lies within this core.", objectives = "Obtain an Ancient Sentry Construct Memory Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38503] = { id = 38503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 020 - Helheim - ZTO" }
quests[38504] = { id = 38504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Bear Twins" }
quests[38505] = { id = 38505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineers: Not COMPLETELY Useless", description = "Unfortunately, I have no idea how to access any information within this core. But I know someone who does.\n\nHead over to \"Like Clockwork\", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.", progress = "You're here from Alard's shop? What does that musclehead want now?", completion = "Oh, a memory core? One moment.", objectives = "Bring the Ancient Sentry Construct Memory Core to Timofey Oshenko in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38506] = { id = 38506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Scratch", description = "I think I have just the thing to extract the information from this core for you.\n\n<Timofey loads the core into the hopper of a clearly goblin-made machine, then covers his ears.>\n\nYou may wish to avert your eyes, blacksmith.", progress = "Highborne! Ancient Highborne! What an amazing find!", completion = "...is what I would say if we weren't floating directly above the ancestral home of the Highborne. You need this translated or something?", objectives = "Bring the Ancient Highborne Data Printout to Professor Pallin in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38507] = { id = 38507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Leysmithing", description = "I could spend hours poring over the details of this fascinating manuscript!\n\n...is what I would say if this weren't the simplest of tasks for someone of my skill level. It's about something called \"Leysmithing\". Here.\n\n<The gnome scribbles down a translation on the back of the scroll.>\n\nThere it is, word-for-word. Bring me something interesting next time.", progress = "Did you find the engineering shop?", completion = "I hadn't even thought far enough ahead to realize you'd need this to be translated, too. Good thinking.\n\nSee, this is why I keep adventurers like you around the shop.", objectives = "Bring the Leysmithing Guide to Alard Schmied in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38508] = { id = 38508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Bear Twins - Reward" }
quests[38509] = { id = 38509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 021 - Helheim - ZTO" }
quests[38510] = { id = 38510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 021 - Helheim - ZTO" }
quests[38511] = { id = 38511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 022 - Helheim - ZTO" }
quests[38512] = { id = 38512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oakleaf" }
quests[38513] = { id = 38513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highmountain Smiths", description = "I think we've gone as far as we can go with what I know, {name}.\n\nThe tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.", completion = "You, outsider, think yourself worthy of our wisdom?", objectives = "Speak with Barm Stonebreaker in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38514] = { id = 38514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Not Worthy", description = "You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them.\n\nWe do, however, respect craftsmanship and discipline.\n\nLet's see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.", progress = "I'm waiting, outsider.", completion = "The craftsmanship is good, but the quality is feeble at best.\n\n<Barm snaps the gauntlets in half and throws them to floor>\n\nYou have proven yourself worthy of my tutelage however.", objectives = "Use your blacksmithing skill to craft a pair of Leystone Gauntlets for Barm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38515] = { id = 38515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature Provides", description = "This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion.\n\nLocal ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux.\n\nGo and gather some foxflower that we can turn into a usable flux.", progress = "How goes the search for foxflower?", completion = "Excellent work. Let's get these turned into flux right away.", objectives = "Obtain 10 Foxflower.\n\nIf you are not an herbalist, you can purchase Foxflower on the Auction House, or you can obtain it from another player.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38516] = { id = 38516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 022 - Helheim - ZTO" }
quests[38517] = { id = 38517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tayla's Rescue" }
quests[38518] = { id = 38518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From One Master to Another", description = "Now young one, go back to your master\nin Dalaran and continue to practice your swing. We'll always be here if you wish to come back and learn more.", completion = "I see, the strength of their work comes from the technique of their hammer strikes. Very interesting...", objectives = "Go back to Alard in Dalaran and share what you've learned from the Tauren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38519] = { id = 38519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grayheft", description = "Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor.\n\nMy father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul.\n\nI would very much like to have it back.", progress = "I have no patterns for helms or boots.\n\nA tauren who cannot survive a few blows to the hoof has no place in battle. Boots are of little use to us.\n\nA helm is a coward's armor. I am sorry if this offends you, but it is true.\n\nLegplates, however, do play a vital role. I will gladly share this pattern with you, once you bring me my father's hammer.", completion = "Thank you, {name}.\n\nThank you.", objectives = "Obtain Grayheft, Ancient Hammer of the Highmountain Tauren from Kubrul within the Deep Roads cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38521] = { id = 38521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tayla's Rescue - Reward" }
quests[38522] = { id = 38522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Just Weapons and Armor", description = "You know, we aren't just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors.\n\nThey should sew in full plate gauntlets if they're really all that worried about their poor little thumbs.\n\nAnyhow, I have a recipe I think an adventurer like you might be interested in. Let's try it out.", progress = "Let's get to work. I think you'll enjoy this.", completion = "Let me take those bars, make a few adjustments and...\n\nTa da! Hoofplates for your mount!", objectives = "Craft 4 Hard Leystone Bars and 24 Hard Leystone Nails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38523] = { id = 38523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone Hoofplates", description = "Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod.\n\nI'll share the pattern when you return.", completion = "Now that Mei's fit the plates to your mount, you should be able to put them on easily yourself.\n\nOh, and before I forget, here's the pattern. Enjoy!", objectives = "Approach Mei Francis in Dalaran while mounted to have your Leystone Hoofplates fitted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38524] = { id = 38524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsmith Nal'ryssa", description = "Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I'd follow up myself, but anything described as \"demon-infested\" is a little too exotic for my tastes.\n\nI just make the armor. I prefer not to wear it.\n\nYou, though... you could follow up on this tip. Be on the lookout for Nal'ryssa. From what I hear, she's a hell of a smith.", completion = "You here to lend us a hand?", objectives = "Report to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38525] = { id = 38525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of the Team", description = "You're a blacksmith?\n\n<The elf looks down at your hammer.>\n\nStill working in leystone, are you? I might be able to help you out.\n\nAlliances out here are hard-won. You've got a pretty face, but that's no guarantee that you aren't working for the demons. I can't afford to trust you yet.\n\nDon't come back until you're caked in demon's blood. Then we'll talk smithing.", completion = "That'll do.", objectives = "Slay 40 demons within Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38526] = { id = 38526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smith Under Fire", description = "You lack recipes for boots?\n\nWhat, were you trained by a tauren or something?\n\nHurry up, then. We probably have a few minutes before the demons attack again. Here's a pattern - show me your work.", progress = "Watch your step out here on the front lines. This isn't your peaceful floating city's blacksmithing shop.", completion = "Not bad, {class}. You know how to swing a hammer.", objectives = "Follow Felsmith Nal'ryssa's instructions to craft Leystone Boots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38527] = { id = 38527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nal'ryssa's Technique", description = "Listen, {class}. We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn.\n\nBring me materials. Lots of them. When you return, we will have much to discuss.", progress = "Are you ready to learn?", completion = "Good. Now let's get to work.", objectives = "Obtain 60 Leystone Ore and 60 Felslate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38528] = { id = 38528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone's Potential", description = "As I'm sure you've deduced, all of the leystone recipes you know can be improved.\n\nBy learning to harness leystone's true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I'll show you.\n\nWe'll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.", progress = "Keep it up, {class}.", completion = "Solid work.\n\nLeystone is a fickle metal. Its armguards benefit from the addition of brimstone, but to improve the production of shoulderpads? Enchanting dust. Helms benefit from uncarved gemstones. And so on.", objectives = "Use Felsmith Nal'ryssa's technique to craft a set of Masterwork Leystone Armguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38529] = { id = 38529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 023 - Weeping Bluffs - ZTO" }
quests[38530] = { id = 38530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firmament Stone", description = "When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered.\n\nUrael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do.\n\nGain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.", completion = "You have returned, {name}. Have you come for more training?\n\nWhat? The Firmament Stone?\n\n\n\nThat's another matter entirely.", objectives = "Speak with Barm Stonebreaker in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38531] = { id = 38531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone Mastery", description = "Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone.\n\nCraft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.", progress = "Remember, {name}: I do not tolerate sloppy work.", completion = "<The tauren carefully looks over your handiwork, brows furrowed.>\n\nYou've learned some things, I see.\n\nVery well. You have succeeded.", objectives = "Speak with Thala Steeltotem to purchase a Leystone Armor Stand, then hang all eight pieces of Leystone Armor on it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38532] = { id = 38532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Hammered By The Storm", description = "Your hammer looks weak, and would probably break upon striking the Firmament Stone.\n\nThe vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls.\n\nThe goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires.\n\nDefeat her and you may be able to acquire such a hammer.", progress = "Were you able to get your hands on one?", completion = "<Barm examines the hammer, turning it slowly in his hands.>\n\nNow THIS is a hammer!", objectives = "Go to the Maw of Souls and recover an Ancient Vrykul Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38533] = { id = 38533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tribal Knowledge", description = "First, however, you'll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe.\n\nPerhaps you should seek another smith if you wish to discuss demonsteel patterns.", completion = "I wouldn't expect the tauren to part with their recipes easily. We are not quite as... bull-headed as they are, but even our recipes will come at a price.\n\nStill, you have earned access to the Firmament Stone, and proven the path to another great anvil, should Urael and I need it.\n\nYou have earned this recipe, as a token of our thanks.", objectives = "Report back to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38534] = { id = 38534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Armguards", objectives = "The armguards you've made are impressive, but you can provide the same level of protection without wasting so much raw material.\n\nHere, let me show you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38535] = { id = 38535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimbil's Journey" }
quests[38536] = { id = 38536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Waistguard", objectives = "Excellent smithing.\n\nNow, allow me to show you a trick I use to conserve resources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38537] = { id = 38537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Pauldrons", objectives = "Your anvilwork is to be commended, but the recipe you're using is unnecessarily wasteful.\n\nTry this instead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38538] = { id = 38538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Boots", objectives = "We don't tend to smith many boots up here, but even I can tell that you're using too much metal for the sole.\n\nHere's a way to cut back on your resource costs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38539] = { id = 38539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Gauntlets", objectives = "The Illidari certainly do like to waste ore, don't they?\n\nYou should craft them this way instead. You'll thank me later.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38540] = { id = 38540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Helm", objectives = "Don't tell Thala and Barm, but I do keep a few helm patterns around, mainly for amusement and decoration.\n\nTake a look at this one. You'll get similar results with much less need for raw material.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38541] = { id = 38541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Greaves", objectives = "Now that you've done it the easy way, try this.\n\nIt's more difficult, but it will save you loads of materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38542] = { id = 38542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonsteel Breastplate", objectives = "The amount of ore you're wasting on that pattern is simply unacceptable. We should conserve wherever possible: it's better for the land and easier on the pocket.\n\nPlease, use this plan instead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38543] = { id = 38543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Armguards" }
quests[38544] = { id = 38544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Waistguard Crafted" }
quests[38545] = { id = 38545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Pauldrons Crafted" }
quests[38546] = { id = 38546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Boots Crafted" }
quests[38547] = { id = 38547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Gauntlets Crafted" }
quests[38548] = { id = 38548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimbil's Journey - Reward" }
quests[38549] = { id = 38549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Helm Crafted" }
quests[38550] = { id = 38550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Greaves Crafted" }
quests[38551] = { id = 38551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Demonsteel Breastplate Crafted" }
quests[38552] = { id = 38552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Hal'shara's Tomb", description = "The tomb, I've found it.", objectives = "Raid the tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38557] = { id = 38557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Invasion Point: Devastation" }
quests[38558] = { id = 38558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Ya Later, Oscillator", description = "Those jawless mooks are actually trying to salvage parts from our ship! They can't possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations.\n\nIn any case, I need a crystal oscillator for our new transponder. It's the shiniest part of the whole system, they're bound to have it set aside somewhere!", progress = "Did you find the oscillator?", completion = "<Overspark examines the crystal carefully.>\n\nYep, still shiny.", objectives = "Collect the Crystal Oscillator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38559] = { id = 38559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worthy of the Stone", description = "You have nothing more to prove to me, {name}. Your training is complete.\n\nOnly a very small herd of smiths have earned the right to the Firmament Stone. You should speak with Muirn Ironhorn, who maintains vigil over our sacred stone. He will tell you what to do next.", completion = "A new face? It's been years...\n\nThis is the Firmament Stone. Memorize her curves. Learn her intricacies. If you truly wish to push your smithing skill to the next level, I predict that you will be spending a lot of time at her side.", objectives = "Speak with Muirn Ironhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38560] = { id = 38560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "Collect tracking maps to find the location of the killer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38561] = { id = 38561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", completion = "I was too late to give you the message. I am truly sorry. These poor shamans... if only I had known sooner!\n\nGul'dan has prepared everything for his ritual. He will use the cipher and his own fel magic to corrupt an elemental lord and use it to sunder the elemental link to the land. This will cause a massive upheaval across Draenor!", objectives = "Speak with the warlock at Lion's Watch in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38562] = { id = 38562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun since Teron'gor's original assault. Now suddenly the Sargerei attacked and blew open a hole into one of the underhalls.\n\nCorruption leaks from that breach. We must investigate!", completion = "More of my ancestors' souls plundered by Gorefiend! This must end once and for all. Gorefiend must be put down!", objectives = "Locate and stop the source of corruption underneath Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38563] = { id = 38563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flower-Pickers and Potion-Quaffers", description = "Now that we know the foxflower flux is safe to use, we can start stocking it. That being said, I don't particularly feel like picking flowers. Do you feel like picking flowers? Didn't think so.\n\nGo talk to the alchemists and herbalists across the way. I'm sure we can set up some sort of work order arrangement.", progress = "Have you spoken with the alchemists and herbalists yet?", completion = "Now that that's all taken care of, we can move on to improving our recipes.", objectives = "Speak with Linzy Blackbolt and Kuhuine Tenderstride to secure a work order for Foxflower Flux.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38564] = { id = 38564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sweet Bargain", description = "Reading over this research, I found an interesting method that I'd like you to try.\n\nThe method would require us to chill the metal to sub-freezing temperatures during the pre-tempering phase. Simple water quenching won't do.\n\nGood thing you can't walk two steps in this city without bumping into a frost mage! See if you can recruit one for the shop, {name}.", completion = "Well done, {name}. Now let's put her to the test!", objectives = "Find a frost mage in Dalaran to chill your quenching trough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38565] = { id = 38565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sargerei Menace", description = "This attack surprised our defenders. Forces are marshalling to push them out, but it will take some time for them to arrive.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "Slay 12 Sargerei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38566] = { id = 38566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A United Force", description = "The paladins of Azeroth must stand united behind a single leader. With Tirion's passing, you are the one most worthy to wear the mantle of Highlord.\n\nIf you agree to accept this duty, inscribe your name into the Libram of Ancient Kings and I will address the masses on your behalf.\n\nThe Order of the Silver Hand is reborn, with you as its champion!", progress = "Yes, Highlord?", completion = "We've done it, Highlord {name}.\n\nThe Order of the Silver Hand is reborn!", objectives = "Establish the Order of the Silver Hand using the Libram of Ancient Kings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38567] = { id = 38567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: War Council", description = "Your garrison is in an uproar. Warchief Vol'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...", completion = "<The Warchief studies a map of Tanaan Jungle and its surroundings, his brow creased with worry.>\n\nAh, Commander {name}! Voice of da Horde in Draenor. Ya done well here, bringin' da fight ta our enemies. Thrall tells me ya exceed his every expectation.\n\nIt be time ta finish dis. Are ya ready?", objectives = "Speak with Warchief Vol'jin inside the Town Hall of your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38568] = { id = 38568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Shipwright", description = "Whatever be left of da Iron Horde be fallin' back ta Tanaan Jungle, where Gul'dan is turnin' them into sumthun' even worse. A frontal assault be suicide.\n\nBut da seas be open. If we attack by both land an' sea, Gul'dan got ta fall back somewhere. {name}, it be time ta build a shipyard!\n\nWe need local resources. Go to da Iron Docks. Gazlowe's boys are already there. Gather any equipment ya find, and see if ya can recruit us a proper Horde Shipwright!", completion = "Commander! I was hoping some backup would arrive. This place is going crazy. The Iron Horde retreated from the Foundry and now, under Gul'dan's orders, they're using these docks to flee to Tanaan.\n\nBut my people found something that might interest you, if you act fast...", objectives = "Travel to the Iron Docks and speak with Sammy Fivefingers. Your Garrison Flight Master can provide transport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38569] = { id = 38569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Docks", description = "We need to get control of this situation. We thought these docks would be all but abandoned. Instead, Gul'dan has ordered the Iron Horde to retreat to Tanaan, and many are using this harbor to make their getaway.\n\nWe need to clear a path for your salvage team. Lay waste to them! Every foe we slay here is one less convert for Gul'dan's wretched demon-worshipping army.", objectives = "Kill 1 Iron Horde orcs and 50 ogron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38570] = { id = 38570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Derailment", description = "Some orcs have spoken out against Gul'dan, and they've been taken prisoner. One of them is what you'd call an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" This guy's good. Designed all these docks, as well as the big dreadnaughts you fought around Shattrath.\n\nIf my scouts are right, he's in a prison train as we speak... And I betcha he'd be willing to defect!\n\nGather up some explosives and meet Durotan next to the train to the south.", progress = "Commander, it's you! Good, I need someone steady at my back.", completion = "We confirmed that Solog Roark is aboard this prison train, but it's locked up tight. Oh - you brought explosives? Hmph. Those goblin friends of yours are always prepared.\n\nLet's bust this box open and convince that shipwright to join our cause...", objectives = "Collect Explosive Charges and a Detonator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38571] = { id = 38571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Train Gang", description = "My warriors will surround and cover the train car. Hit the detonator to blow open the doors.\n\nI will speak to Roark and convince him to defect to our cause. He built all of this - he's our best hope for building a shipyard of our own.\n\nIf this doesn't work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.", completion = "Lower your weapon, stranger. Blackhand is dead and our new \"Warchief\" just signed my death sentence. It looks like I'm going mercenary.\n\nYou want to build a shipyard? Then you want me.", objectives = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38572] = { id = 38572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook, Line, and... Sink Him!", description = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place.\n\nBut I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar.\n\n<Roark spits.>\n\nGul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", progress = "I will rebuild.", completion = "<Solog Roark takes in the view of his harbor one final time.>\n\nWe built it all for nothing, {class}. Gul'dan will claim whatever your troops do not destroy.\n\nNext time, I will build something that will last.", objectives = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38573] = { id = 38573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Remains", description = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people.\n\nYou and your Frostwolf allies still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!\n\nLet your people know I am coming.", completion = "Ah, ya found us a shipwright? Good! Ya followers be eager ta take on da open seas.", objectives = "Report back to Vol'jin at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38574] = { id = 38574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hands on Deck", description = "Let's put dis \"Iron Shipwright\" ta work, commander. If we ta take Tanaan from both land an' sea, we gonna need a shipyard. Work wit' Roark an' make it happen!\n\nHe be surveyin' tha land along tha road west of Frostwall.", progress = "I'll need building supplies, commander. Can't build docks of ice and snow.", completion = "<Solog Roark scans the horizon.>\n\nThis will do. It's a good deepwater harbor. We can gut that old warship down there to make your first transport. Moving supplies up and down these cliffs will be a chore, but they'll give us additional security in case we're attacked.\n\nWe'll make it work. Are you ready to get building?", objectives = "Construct a Level 1 Shipyard for your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38575] = { id = 38575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beachhead" }
quests[38576] = { id = 38576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Meet at Light's Hope", description = "With you on our side, I know the Legion will fall! But before we march on the Broken Isles, we must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.\n\nPaladins the world over are on their way to the ceremony. I know Tirion would want you there most of all.", completion = "It is fitting that you are here.\n\nTime and again, you have fought to save our world. Now, I fear I must ask you to undertake an even greater act of service.", objectives = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38577] = { id = 38577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Durotan has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", completion = "Now you see what we face here. We will keep as much pressure here as we can so your base can remain free to attack all over the jungle.", objectives = "Go to the Iron Front and speak with Durotan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38578] = { id = 38578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message of Terrible Import", description = "Your scout... he got me out of that hellish place. Fel orcs surprised us out in the jungle and dragged us up the mountain. They tortured us... killed all but me. I fear one of us may have given up our secret before the end.\n\nI must ask you to go to the home of our order. Speak with Lagar, my leader, tell him... tell him Gul'dan knows.", progress = "This is most unfortunate.", completion = "We will speak more of this later, but thank you.", objectives = "Go to the Vault of the Earth and speak with Lagar the Wise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38579] = { id = 38579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Xanzith the Everlasting" }
quests[38580] = { id = 38580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Overlord Ma'gruth" }
quests[38581] = { id = 38581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Exarch Maladaar has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", completion = "Now you see what we face here. We will keep as much pressure here as we can so your base can remain free to attack all over the jungle.", objectives = "Go to the Iron Front and speak with Exarch Maladaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38582] = { id = 38582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Old Friends", description = "I sense a powerful dark presence here, {name}, but it is not of Xavius. This feels too familiar.\n\nI sense a druid's touch here, a druid twisted by the shadow of the Nightmare.\n\nWe must deal with this threat if we are to find Xavius. I will take to the skies and lend you my aid.\n\nFind this corrupted druid and cut down his tainted and twisted plants.", completion = "Know this, {name}. You did the only thing you could.\n\nWhen a mortal has become corrupted by the nightmare, there is no return. Only death will set them free.", objectives = "Kill 50 Corrupted Creatures in Moonrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38583] = { id = 38583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden" }
quests[38584] = { id = 38584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden" }
quests[38585] = { id = 38585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Defeat the Shadow Council at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38586] = { id = 38586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", completion = "Word of your success has already been passed on by our scouts. \n\nLok'tar!", objectives = "Defeat the Shadow Council at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38587] = { id = 38587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Remember the first war, we know the destruction the legion can cause if they are unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38588] = { id = 38588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. We know the destruction the legion can cause if they are left unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38589] = { id = 38589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ravager Broodlord" }
quests[38591] = { id = 38591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ravager Sack" }
quests[38592] = { id = 38592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Group" }
quests[38593] = { id = 38593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ravager Spear" }
quests[38594] = { id = 38594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Group" }
quests[38595] = { id = 38595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion's Fury", description = "The loss of Cenarius to the nightmare is a devastating blow to us all.\n\nThough Malfurion's rage is justified, his hatred of Xavius has burned for centuries and I fear that his blind rage will be used as a weapon against him.\n\nMay Elune guide us in our search for him, lest we have yet another friend to mourn today.", completion = "Oh, {name}...\n\nWhat is becoming of this precious land?", objectives = "Speak with Ysera to search for Malfurion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38596] = { id = 38596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING Nightmare 02", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", sourceObjective = "Defeat Botanist Darkgrove", sourceObjectiveStatus = "unverified-source-field" }
quests[38597] = { id = 38597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[38598] = { id = 38598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST: Craft Some Legplates", description = "The Highmountain tauren craft their legplates piece-by-piece, then assemble them all at the end.\n\nSeems pretty slow and unnecessarily arduous if you ask me, but we should start here before making any efficiency improvements.\n\nHere's some leystone. I've added the recipe into your workbook, as well. Let's give this a shot!", objectives = "Use your Blacksmithing skill to craft a pair of Handcrafted Leystone Legplates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38599] = { id = 38599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infrastructure Improvements", description = "<Sir/Ma'am>, we built a vehicle to take ya up to the Throne of Kil'jaeden but whenever we try a test flight the navigation system goes crazy!\n\nIn my expert opinion it's 'cause of that crazy demon magic the Iron Horde is playing around with up there.\n\nIf you could travel up there and place these telemetry beacons we can program the vehicle and give you a stable flight all the way up.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", completion = "Hey welcome back! The signal's coming in loud and clear and the ship's good to go!\n\nWhen you're ready to head back up just take the rocket for the fastest ride on Draenor! We set it up over near Gargash.", objectives = "Place 5 G-X3 Telemetry Beacons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38600] = { id = 38600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fel Saberon Shaman" }
quests[38601] = { id = 38601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Saberon Supplies" }
quests[38602] = { id = 38602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Fel Spike" }
quests[38603] = { id = 38603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Signal", description = "<Sir/Ma'am>, we built a vehicle to bypass the Horde camp and take you to the Throne of Kil'jaeden! There's one problem, the concentrated fel energy up there is causing the navigation system to go haywire!\n\nI'll need you to place some sensors along the edge of the summit. With them in place we can stabilize the flight controls.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", completion = "Welcome back!\n\nWe're getting a strong feed from those sensors! The crew locked the navigation system on to the signal and everything should be good to go!\n\nWe set the machine up next to Skyguard Thann.", objectives = "Place 5 Pentangulate-o-tron 2000s.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38604] = { id = 38604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Saberon Shaman" }
quests[38605] = { id = 38605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Saberon Blademaster" }
quests[38607] = { id = 38607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gates of Valhallas", description = "Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all.\n\nSkovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas.\n\nThe giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught.\n\nSpeak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.", sourceObjective = "Speak with Vedhir.", sourceObjectiveStatus = "unverified-source-field" }
quests[38608] = { id = 38608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaim Valhallas" }
quests[38609] = { id = 38609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Iron Tunnel Foreman" }
quests[38610] = { id = 38610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Gates of Valhallas -Tracking quest - Titan Vehicle - Bonus Objective" }
quests[38611] = { id = 38611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Thorignir", description = "In the summit of storms the dragons await. Born of the gods, they will test your will. \n\nThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.\n\nA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", completion = "These vrykul are so boring! Why does Nathanos send me on missions like this? Does he really think the Aegis is here?\n\nI hope you've come to stir up some trouble.", objectives = "Meet with Dread-Rider Cullen outside of Hrydshal to begin the trial of the Thorignir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38612] = { id = 38612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grapple a Day", description = "So some old magic vrykul is helping us out? I guess that's good, but this trial of yours might be tricky. You see, the only way up that mountain, is through those big walls.\n\nYou know, the ones with the mean-looking drakes on them.\n\nI scouted a bit, but couldn't get too far without those drakes trying to make lunch out of poor Duchess. The vrykul have them trained, which can't be good.\n\nI say we sneak in. I managed to snag a few grapple launchers earlier. Grab one and meet me outside the city walls.", completion = "Yes, that should do quite nicely.", objectives = "Pick up a Stormforged Grapple Launcher and meet Dread-Rider Cullen outside the wall of Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38613] = { id = 38613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Wings Required", description = "That thing looks like it's got the range to get us over the wall. There's a good spot to hook onto right past us - you should be able to spot it from here.\n\nOnce you're inside, do me a favor and see if you can distract the guards so I can slip through. I'll see what else I can find out about these vrykul.", completion = "Those vrykul were so distracted seeing someone flying through their village, they never noticed me slip by. \n\nI hope that didn't get you too much unwanted attention.", objectives = "Use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38614] = { id = 38614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Weather the Storm", description = "When I was scouting this place out, I noticed the vrykul here are no strangers to the treacherous mountain path we're trying to get to. They've got some specialized equipment they're using, and if I were you I'd try to get my hands on some.\n\nYou'll want to find some climbing treads to keep your grip and an oiled cloak to keep you dry. They've also got these stones they carry to keep the lightning at bay, so you'll want to pick one of those up as well.", progress = "Were you able to get all the gear you needed?", completion = "Well, the sizing might be a bit big, but I think you can make them work. \n\nThat path doesn't look pleasant, so it'll help to be prepared.", objectives = "Collect Climbing Treads, an Oiled Cloak, and an Enchanted Lodestone from Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38615] = { id = 38615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impalement Insurance", description = "It looks like the elements aren't the only thing you'll need to worry about going up that path. Those harpoon launchers on the wall look pretty nasty, and unless we take them out first, they're likely to make short work of anyone trying to scale that path.\n\nThey're up on top of the walls, so you'll need to use that grapple launcher to get to them. Just try not to end up drake food!", completion = "We won't have to worry about those scrap heaps anymore! \n\nIt looks like we've got a hitch in our plan though. That bridge was the only way up.", objectives = "Grapple on top of the walls and dismantle 7 Tideskorn Harpoon Launchers atop in Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38616] = { id = 38616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", progress = "What have we here?", completion = "Good thinking. If the vrykul can use the drake scales for their armor, why not us? \n\nIt shouldn't be too tough to work this into something serviceable.", objectives = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38617] = { id = 38617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Way", description = "Wait, do you still have that grapple launcher? I think you can still get to the path if you can launch from the top of that tower. The gap doesn't seem too bad there.\n\nOf course, we'll have to take out the big guy out front first. He looks tough, but I think we have a chance if we can flank him.", progress = "This should be a piece of cake!", completion = "What a fight! \n\nAnd here I thought this place would be boring.", objectives = "Defeat the Drekirjar Champion in Hrydshal, then climb to the top of the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38618] = { id = 38618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Above the Winter Moonlight", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", completion = "You are here for the trial? I'm afraid you might be too late.\n\nThis battle with these Felskorn has taken its toll. I am too weak to grant you the power you seek...\n\nBut perhaps you may be able to help...", objectives = "Grapple across from the tower and climb to the top of the mountain path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38620] = { id = 38620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Assassin" }
quests[38624] = { id = 38624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry Thunder!", description = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. \n\nThe dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Be they Felskorn or not, their malice has caused suffering to my brood. Their toll must be paid in blood.\n\nSpeak to Vethir when you are ready.", completion = "<The raven squawks, and Havi's voice fills your head>\n\nYou are indeed mighty, as the trial shows. \n\nBut valor is a different animal - one you think to tame?", objectives = "Fly with Vethir and kill 150 of the God-King's allies in Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38625] = { id = 38625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook & Sinker" }
