quests[38640] = { id = 38640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Anti Pale Equipment" }
quests[38641] = { id = 38641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Elune", description = "Cenarius is in danger.\n\nIf his condition is not reversed soon, he will be lost to the Nightmare that threatens the Emerald Dream. To spare him that fate, we must have the Tears of Elune - the same relic you were sent here to retrieve.\n\nElune's temple is not far. Go there. Find Lyanis. Show her my seal and instruct her to release the tears into your custody.\n\nHurry, {name}. Time is short.", completion = "You - you bear the mark of The Dreamer. Elune be praised!\n\nYou've arrived just in time, visitor. Shaladrassil's roots are at our doorstep...", objectives = "Speak with Lyanis Moonfall at the Temple of Elune.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38642] = { id = 38642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrykul Longboat" }
quests[38643] = { id = 38643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Village in Peril", description = "The corpse of Darcy Heathrow lies before you pierced by several arrows and knife wounds.\n\nIn one hand she clutches a note, written with a feeble hand, that reads:\n\n\"The dead march on Bradensbrook.\n\nHelp us, please!\"", completion = "We don't need any help, and we don't like strangers wanderin' around on our land.", objectives = "Speak to Mayor Heathrow at Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38644] = { id = 38644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmsteads", description = "Forgive us, stranger. Mayor Heathrow has been under a lot of stress recently.\n\nI can't blame him: his own daughter, Penelope, has been missing for two days.\n\nIn fact, we could use information on several farmsteads to the south: Mayor Heathrow's house, Granny Marl's farm, and the Radcliffes' dock. Can you go check on the situation out there?\n\nHelp us, and perhaps the mayor's heart will soften.", progress = "How does it look out there?", completion = "I'm sorry for my suspicion earlier. We're all on edge with the recent attacks.\n\nI couldn't be more grateful to you and your friend.\n\nThanks to you, our situation is under control now. We've got a lot of rebuilding to do, but we'll survive.", objectives = "Check on the Heathrow house, Granny Marl's farm, and the Radcliffes' fishing dock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38645] = { id = 38645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of the Night", description = "I am no enemy to these people, but there is no convincing them of that.\n\nTheir village has come under attack by some very old friends of mine. Friends who are no longer... living.\n\nThere's no telling who or what controls them, but in life these noble soldiers would never engage in such acts. That's a mystery for another time.\n\nFor now, help me earn the trust of these villagers. Strike down the Black Rook enemies who are terrorizing their citizens.", progress = "The attackers are night elves, yes, but they are not the same night elves I once knew.", completion = "Good. These innocent villagers have done nothing to deserve these attacks. You have done well to help them.", objectives = "Kill 12 Risen Assassins, Black Rook Falcons, or Risen Hounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38646] = { id = 38646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sight For Sore Eyes", description = "Do you see those ravenous birds flying above my farm? Vicious creatures are spreading their filth an' eatin' my crops.\n\nI'd get rid of them with my trusty gun, but my eyesight's gone downhill.\n\nTake this flare gun and mark them for me.\n\nOnce I get my sights on them, I'll make 'em scatter.", progress = "Heh? Is that you again?", completion = "Well love, we sure did take care of them! Thank you, {class}. Glad ta see I 'aven't lost my touch.", objectives = "Use Granny's Flare Gun to mark 6 Black Rook Falcons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38647] = { id = 38647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Corn!", description = "I've got a full summer's corn harvest just sittin' out in the field. I need some muscle to bring it in before the night elf raiders can destroy it.\n\nGet out there and bring me those crops, and I'll reward you handsomely.\n\nThe folks back in town need this food, and I sure as heck ain't eating rats for another winter.", progress = "The corn isn't gonna gather itself.", completion = "All right, I'll get those barrels loaded up and delivered to the village in no time.\n\nThank you, {name}. There'll be a lot of full bellies because of you.", objectives = "Collect 5 Barrels of Corn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38648] = { id = 38648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Orders", description = "The letter is written in midnight ink:\n\n\"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\"\n\n- K.R.\"\n\nPerhaps Jarod Shadowsong will want to see this.", sourceObjective = "Return to Commander Jarod Shadowsong at Bradensbrook.", sourceObjectiveStatus = "unverified-source-field" }
quests[38649] = { id = 38649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence in the City", description = "There is a troubling silence from Suramar City this day.\n\nOculeth just informed me that the teleporter to the Waning Crescent has gone dark. He is not able to reach Vanthir, nor am I.\n\nWhile I am hesitant to believe something dire has happened, I do feel this warrants investigation.\n\nSpeak with Oculeth and see if he can transport you to the Waning Crescent. We need to find out what happened.", completion = "Something is amiss. I can feel it in my bones.", objectives = "Speak to Chief Telemancer Oculeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38654] = { id = 38654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Giant Raptor" }
quests[38655] = { id = 38655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Cause", description = "The massive roots of Shaladrassil are spreading a horrible corruption throughout the forest.\n\nIf we are to save Val'sharah, we will need to find a way to stop the encroachment of the world tree.\n\nIf you bring me enough corrupted root samples, I may be able to discover their secrets.", progress = "Have you collected the root samples?", completion = "It is as I feared, {race}. This corruption is... irreversible.\n\nOur only course of action is to somehow find a way to fight it at its source.", objectives = "Collect 30 Corrupted Root Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38656] = { id = 38656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of the Demon", description = "The demonic rune glows in your hand, emanating dark power. A single word, inscribed in demon tongue, glows coldly... \n\n...GRAVAX...", completion = "I am impressed that you were able to defeat such a powerful demon. We are fortunate that you have lent us your aid.", objectives = "Return the Demonic Emblem to Isoraen Nightstar at the Temple of Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38657] = { id = 38657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Swamp Sword" }
quests[38658] = { id = 38658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid For the Wounded", objectives = "Revive 10 wounded allies by using the moonstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38660] = { id = 38660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Corruption", description = "All along the battlefield, the satyrs have erected dark totems that spread the corruption of the Emerald Nightmare upon the land.\n\nAs long as the Nightmare totems remain, we will not be able to hold back the corruption!\n\nIf you truly wish to aid us in the fight, destroy the totems that you encounter upon the battlefield.\n\nOur survival depends on it!", objectives = "Destroy 6 Nightmare Totems on the Battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38661] = { id = 38661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare Bombs", objectives = "Revive 8 Nightmare Bombs on the Battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38662] = { id = 38662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears for Fears", description = "The Tears of Elune are a sacred artifact, protected by my order for thousands of years. I tell you this so that you may understand the gravity of your request.\n\nThat said, Ysera is noble and wise and I trust in her guidance. You will find the tears in a vault at the eastern edge of the temple grounds.\n\nProceed with caution though, as that area has been overrun by demons.", progress = "Do you have the Tears of Elune?", completion = "Xavius has stolen our sacred artifact?\n\nElune, forgive me. I have failed you.", objectives = "Retrieve the Tears of Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38663] = { id = 38663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Die is Cast", description = "Thanks to your efforts the temple is safe, for now.\n\nBut the Tears of Elune are stolen and Shaladrassil, the world tree that once protected this land, is now an instrument in the hands of our enemy. The Emerald Dream itself is being overrun by Nightmare.\n\nThe hearts of our people falter, their faith tested like never before. Return to Ysera with my report, {name}, such as it is.\n\nI shall plead with Elune with what time I have left here. May we somehow yet prevail.", completion = "This is dire news indeed, {name}.\n\nDraw upon your courage now, friend, for Azeroth needs her heroes more than ever before.", objectives = "Speak with Ysera at the Grove of Cenarius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38664] = { id = 38664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saved Family 1" }
quests[38665] = { id = 38665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saved Family 2" }
quests[38666] = { id = 38666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Eligible for Grumpy" }
quests[38667] = { id = 38667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon's Trail", description = "Xavius! How many times must I end that wretched satyr before he stays dead...\n\nWe must get to Shaladrassil and find Xavius before it is too late!\n\nMy wounds are grave, but they will heal... do not concern yourself with my safety. There is little time... we may already be too late...", objectives = "Travel with Archdruid Malfurion Stormrage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38668] = { id = 38668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Last Hope", description = "Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds.\n\nIn the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.", sourceObjective = "Speak with Maiev Shadowsong in the Illidari Cellblock.", sourceObjectiveStatus = "unverified-source-field" }
quests[38669] = { id = 38669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Last Hope", description = "The Vault has fallen to the Burning Legion.\n\nIt pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice.\n\nHelp me, demon hunter, and I will grant you your freedom.", objectives = "Retrieve your new warglaives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38670] = { id = 38670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goredome 2" }
quests[38671] = { id = 38671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Retreat", description = "Is this the end?\n\nOur beloved Malfurion. I saw him in the Dreamer's clutches, but Ysera was... changed. Twisted.\n\nShaladrassil, our mighty world tree, is corrupted beyond recognition.\n\nWe were forced to flee our home without our belongings. Some were heirlooms, sacred to us. Return them to me if you can, {class}, I beg you.", progress = "Have you retrieved them?", completion = "It is not much, but it is better than I could have hoped for. You have our gratitude.", objectives = "Retrieve 5 Shadowfen Heirlooms in Shadowfen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38672] = { id = 38672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Out", description = "We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.", progress = "<The lever seems to control the door.>", completion = "<Pull the lever.>", objectives = "Free both Altruis the Sufferer and Kayn Sunfury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38673] = { id = 38673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormtalon Crone", description = "A wicked coven of harpies have overtaken our village.\n\nIt was the twisting of the forest that forced us out of our village, but now that the harpies have moved in I fear that we may never be able to return.\n\nThe Wormtalon coven are led by a witch called Grelda the Crone. She has made her nest in a cave near our village.\n\nIf their leader is defeated, the remaining harpies will surely flee.\n\nSlay Grelda the Crone and we will be forever in your debt, {class}.", objectives = "Slay Grelda the Crone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38674] = { id = 38674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion's Cure", description = "The cleansed Mooncaps glow radiantly in your hands as you lift them from the waters of the ancient moonwell.\n\nMender Onelle will need the Mooncaps in order to make a healing poultice for Malfurion's wounds.", objectives = "Deliver the Cleansed Mooncaps to Mender Onelle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38675] = { id = 38675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Nightmare", description = "I know only that my husband is somewhere deeper in this twisted forest.\n\nHe is still alive, but it remains to be seen if he is whole.\n\n<Tyrande's expression hardens into a scowl as she peers at you.>\n\nElune herself cannot protect Xavius if he is not.", completion = "No one is safe from this corruption.", objectives = "Track Malfurion's path through the Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38676] = { id = 38676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 025 - Weeping Bluffs - ZTO" }
quests[38677] = { id = 38677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 026 - Weeping Bluffs - ZTO" }
quests[38678] = { id = 38678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Bleeding Hollow Warchest" }
