quests[38680] = { id = 38680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 027 - Weeping Bluffs - ZTO" }
quests[38681] = { id = 38681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 028 - Mountain Cave - ZTO" }
quests[38682] = { id = 38682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Censer of Torment" }
quests[38683] = { id = 38683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Looted Bleeding Hollow Sack" }
quests[38684] = { id = 38684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Leaves", description = "{name}, my friend. You must succeed where I have failed. You must find our dear Malfurion.\n\nAs the Nightmare consumes my thoughts, I hear the voices of these twisted trees. I must cling to sanity long enough to aid you.\n\nVenture into Ash'theran and bring me Corrupted Petals from the fallen denizens there.\n\nWith them, I might find your Archdruid while my mind is still my own.", progress = "Ahh... the fear! The panic!\n\nI haven't the strength to fight much longer...", completion = "The waking world is slipping further and further from my mind. But on the vestiges of this corruption consuming my mind, I sense Malfurion!", objectives = "Collect 5 Corrupted Petals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38685] = { id = 38685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nameless King" }
quests[38686] = { id = 38686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rune Etched Femur" }
quests[38687] = { id = 38687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Enough to Touch", description = "He is near, {name}, I can feel it.\n\nWe must scour this place in search of my husband. I fear if we do not find him soon it will be too late.\n\nYou have been courageous throughout our search. I know you will not fail me now, {name}.\n\nThank you, and please hurry.", completion = "This cannot be!", objectives = "Search for Malfurion within Shala'nir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38688] = { id = 38688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Remains", description = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.", objectives = "Take the Tear of Elune to Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38689] = { id = 38689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Infusion", description = "So many years of imprisonment has left us weak.\n\nThe Vault is overrun with demons.  Kill them and gather their souls to regain your strength.", completion = "The color has returned to your face, {name}.", objectives = "Infuse yourself with 100 energy from fallen demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38690] = { id = 38690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Illidari", description = "Look down there. We are vastly outnumbered.\n\nWe will need more allies on our side if we are to escape from here intact. Free the other Illidari imprisoned within the cells of this chamber.\n\nWe will need everyone to escape this place alive.", progress = "Have you freed those you found in the cells?", completion = "We always knew the Illidari would be called upon to defend this world. It is why we sacrificed everything to become who... WHAT... we are.", objectives = "Free 8 Illidari Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38691] = { id = 38691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarod's Mission", description = "Since Maiev chased after Gul'dan at the Vault of the Wardens, her sisters among the Wardens have been searching far and wide for her whereabouts.\n\nWith so few Wardens remaining, I volunteered to join the search. I hope I will find sign of her within Black Rook Hold.\n\nThe fortress will be well guarded, and I will need help to break through. Help me find her, and I will reward you handsomely.", progress = "Did you have any trouble getting here?", completion = "What does the Legion want with Ravencrest? He was dead and buried ten millennia ago.", objectives = "Speak to Jarod Shadowsong at Ravencrest Mausoleum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38692] = { id = 38692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Aggression", description = "I weep for the Nightborne this day.\n\n<Silgryn gestures out the door.>\n\nElisande demonstrates the ultimate disdain for her people. So many lives... wasted!\n\nAll to relay a message: This is what happens to those who defy her.\n\n{name}, my friend, we must answer her. We must show her that she cannot slay her people without retribution.\n\nFight back, {name}.", completion = "It had to be done.", objectives = "Kill 12 of Elisande's Forces in the Waning Crescent, Starcaller Retreat, and Siren's Vigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38693] = { id = 38693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Feral Dogs", description = "You've done more than enough, {name}. My people and I can clean things up here.\n\nYou should return to town and report on our victory.", objectives = "Return to Anna Thornton at Barreltown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38694] = { id = 38694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regroup", description = "These people may be able to hold out here, but I know for certain that we cannot.\n\nEvery moment we spend here places them in danger of Elisande's forces retaliating against us.\n\nWe need to move. We need to find a place to regroup and recover.\n\nFollow me. I think I know how we can get out of here.", completion = "Oculeth has anticipated our arrival. Good, one less thing to worry on.", objectives = "Escape Siren's Vigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38695] = { id = 38695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crackdown", description = "Thalyssra is right to be concerned!\n\nThe network has not responded to my attempts to re-establish connection with the Waning Crescent. I do not know what happened, but given the circumstances I believe it prudent to investigate in person.\n\n{name}, would you do the honors? I will send you as close to the Waning Crescent as I can.", progress = "Elisande... how could you?", completion = "Someone must have informed the Grand Magistrix of Vanthir's involvement in the rebellion. Such violence is...\n\nElisande... How could you?", objectives = "Investigate the events of the Waning Crescent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38696] = { id = 38696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bleeding Hollow Horror" }
quests[38697] = { id = 38697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword of Truth", description = "Lord Ravencrest's army rises from the dead, but I believe they are controlled by Gul'dan's will.\n\nTake this - Lord Ravencrest's blade, Fal'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth.\n\nTake the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.", objectives = "Place Fal'shathil on the ground, then defeat Black Rook night elves within its holy light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38699] = { id = 38699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competitive Exorcise", description = "Think you're good at sending demons back to the hell from whence they came? Show me!\n\nI once bagged 15 in under 10 minutes. Do better than that and there'll be brew money waitin' for ya.", objectives = "Kill 15 Burning Legion invaders in 10 minutes or less.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38700] = { id = 38700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Steelsnout" }
quests[38701] = { id = 38701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Strange Fruit" }
quests[38702] = { id = 38702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Dead Warrior's Helmet" }
quests[38703] = { id = 38703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Scout Rifle" }
quests[38704] = { id = 38704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Forgotten Iron Horde Supplies" }
quests[38705] = { id = 38705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Elements" }
quests[38708] = { id = 38708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the River" }
quests[38709] = { id = 38709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cave Keeper" }
quests[38710] = { id = 38710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Gathering", description = "A critical decision must be made, {name}.\n\nThe Legion devastated our forces at the Broken Shore. The mightiest army this world has ever known was reduced to cinders in moments.\n\nWe must gather those with the conviction to save our home. Travard of Tyr's Guard and Orik Trueheart have each made plans to do just that, but we must not let them walk alone.\n\nI ask that you seek them out and guide them to Krasus' Landing so that we may make this decision together.", completion = "Thank you for helping us gather together, {name}. We must stand united.", objectives = "Gather Travard and Orik Trueheart, then meet Lord Maxwell Tyrosus at Krasus' Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38711] = { id = 38711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Signet", description = "The night elf was carrying a signet engraved with the crest of the Wardens.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.", completion = "<Jarod gazes at the ring for a long minute before closing his hands around it. He puts the ring in a pocket.>\n\nThis is Maiev's ring. She would never part with it.\n\nShe must be at Black Rook Hold!", objectives = "Take the Warden's Signet to Jarod Shadowsong.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38712] = { id = 38712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Houndmaster Ely" }
quests[38713] = { id = 38713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crusade Calls", description = "((You have just finished the introduction sequence in Dalaran.))\n\nLord Maxwell Tyrosus of the Argent Crusade sent for you. He mentioned knowing of a weapon we could use against the Legion.\n\nAs much as I loathe their ilk, you should go to Krasus' Landing and speak with him. We need every advantage we can muster.", sourceObjective = "Speak to Lord Maxwell Tyrosus at Krasus' Landing.", sourceObjectiveStatus = "unverified-source-field" }
quests[38714] = { id = 38714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maiev's Trail", description = "The fortress grounds are just up ahead. There is a large area to search, but if we split up, I believe we can cover a lot of ground.\n\nSearch the prison cages, the forge, and the guard tower for any signs of Maiev. I will check the upper ramparts and meet you on the other side of the keep.", progress = "We will give this area a thorough search.", completion = "Good work, {name}. There is no doubt that they have already moved Maiev into the prison cells beneath the tower.", objectives = "Search the forge, the saber pens, and the guard tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38715] = { id = 38715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rook's Guard", description = "Black Rook Hold is not the same place I knew. Its walls have crumbled, a ghostly echo of its former glory.\n\nIf Lord Ravencrest has returned, then surely he will have his former officers at his side.\n\nKester Farseeker, captain of the guard.\n\nTrelan Shieldbreaker, peerless master of maces.\n\nStarlys Strongbow, who could split arrows while blindfolded.\n\nIf we stand any chance of entering the tower itself, they must be eliminated.", progress = "Warriors and fighters came from across kaldorei lands to pledge loyalty to Master Ravencrest. We would have followed him to the ends of the earth.", completion = "Thank you, {name}. May their spirits be at peace.", objectives = "Kill Kester Farseeker, Trelan Shieldbreaker, and Starlys Strongbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38716] = { id = 38716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold", description = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.", objectives = "Take the Warden's Signet to Jarod Shadowsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38717] = { id = 38717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Prison", description = "I did not come this far to lose her in the final moments.\n\nMaiev must be in the cells beneath Black Rook Hold.\n\nI scouted above, and the entrance to the prison is guarded by a fearsome jailor.\n\nI will sneak past and take out the guards inside. Defeat Araxxas, take the keys, and then meet me within.", progress = "Do you have the keys?", completion = "Good, these keys should open any of the cells within the prison.", objectives = "Kill Araxxas and collect the Prison Keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38718] = { id = 38718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kur'talos Ravencrest", description = "Lord Ravencrest was a fearless leader, a seasoned commander, a man of integrity and honor, a teacher, and a protector of his people.\n\nMalfurion, Illidan, Tyrande, and I... we were still young when he helped shape our destinies.\n\nThe sigil of his house was legendary. Observe, for a moment, the sigil over his former resting place and I shall tell you more of his legacy.", completion = "The attacking spirits spoke of their lord and master. I fear the Legion has raised Lord Ravencrest to do their bidding. What price was paid for such a sinister revival, I do not know.", objectives = "Examine Ravencrest's Sigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38719] = { id = 38719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari Freedom", description = "<The Illidari demon hunter is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of my... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, but please, save them.", completion = "The other Illidari did not make it, but I owe you my life. There is one thing I learned during my time in the prisons: the demons within Black Rook Hold must die.", objectives = "Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
